export function pubSubOrchestrationLayer(agents, tasks) {
  const subscribers = {};

  function subscribe(agent, event) {
    if (!subscribers[event]) {
      subscribers[event] = [];
    }
    subscribers[event].push(agent);
  }

  function publish(event, data) {
    if (subscribers[event]) {
      subscribers[event].forEach(agent => agent.process(data));
    }
  }

  function allocateTask(task) {
    const selectedAgent = agents.find(agent => agent.canHandle(task));
    if (selectedAgent) {
      selectedAgent.handle(task);
      publish('taskCompleted', { task, agent: selectedAgent });
    } else {
      publish('taskEscalation', { task });
    }
  }

  return { subscribe, publish, allocateTask };
}